// Minimal stub of express for offline logic testing (no real HTTP serving needed for unit tests).
function express() {
  const app = function (req, res, next) { if (next) next(); };
  app.use = function () { return app; };
  app.get = function () { return app; };
  return app;
}
express.static = function () { return function (req, res, next) { if (next) next(); }; };
module.exports = express;
